"""
    Takes a 1-d list of pixels and filters out the very dark pixels. Returns
    the list of non-dark pixels
    """
def filter_out_black(list_of_pixels: Any) -> object {
    return [
        pixel
        for pixel in list_of_pixels
        if (max(pixel) > 0.1)
    ];
}

"""
	Check the given ratio is valid or not. Sum of ratio should be 100
	"""
def check_ratio_sum(ratio: Any) -> object {
    train_ratio = int(ratio[0]);
    val_ratio = int(ratio[1]);
    test_ratio = int(ratio[2]);
    qa_ratio = int(ratio[3]);
    total = train_ratio + test_ratio + val_ratio + qa_ratio;
    if (total != 100) {
        raise ValueError("Sum of all the input ratio should be equal to 100 ");
    }
    return (train_ratio, val_ratio, test_ratio, qa_ratio);
}

"""
    Original text is limited to 72 characters per line, paragraphs separated
    by a blank line. This function merges every paragraph to one line.

    Args:
        text (str): Text with limited line size.

    Returns:
        str: Text with every paragraph on a single line.
    """
def dealign(text: Any) -> object {
    original_lines = text.splitlines();
    paragraphs = [];
    i = 0;
    while (i < len(original_lines)) {
        paragraph_lines = [];
        while True {
            line = original_lines[i];
            i += 1;
            if line {
                paragraph_lines.append(line);
            }
            if (not line or (i == len(original_lines))) {
                if paragraph_lines {
                    paragraphs.append(' '.join(paragraph_lines));
                }
                break;
            }
        }
        if (i == len(original_lines)) {
            break;
        }
    }
    return '\n'.join(paragraphs);
}

